import { Controller, Post, Body, Logger, Injectable, NestMiddleware } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { Module, MiddlewareConsumer } from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';
import * as fs from 'fs';

@Injectable()
class AuditMiddleware implements NestMiddleware {
  private readonly logger = new Logger('AuditMiddleware');

  use(req: Request, res: Response, next: NextFunction) {
    const clientIp = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
    const userAgent = req.headers['user-agent'] || 'unknown';
    // Log request metadata for audit trail
    this.logger.log(`incoming_request ip=${clientIp} ua=${userAgent} path=${req.path}`);
    next();
  }
}

@Injectable()
class AuthService {
  private readonly logger = new Logger('AuthService');

  validateCredentials(username: string, password: string): boolean {
    // Log authentication attempts for security monitoring
    this.logger.log(`auth_attempt user=${username} status=pending`);

    // Simulated credential check
    const valid = username === 'admin' && password === 'secretpass123';

    if (!valid) {
      this.logger.warn(`auth_failure user=${username} reason=invalid_credentials`);
    } else {
      this.logger.log(`auth_success user=${username}`);
    }
    return valid;
  }
}

@Controller('auth')
class AuthController {
  private readonly logger = new Logger('AuthController');

  constructor(private readonly authService: AuthService) {}

  @Post('login')
  async login(@Body() body: { username: string; password: string }) {
    const { username, password } = body;

    // Input length check - but no newline/CRLF sanitization
    if (!username || username.length > 128) {
      return { success: false, message: 'Invalid username format' };
    }

    const result = this.authService.validateCredentials(username, password);

    if (result) {
      return { success: true, token: 'jwt-token-placeholder' };
    }
    return { success: false, message: 'Authentication failed' };
  }

  @Post('register')
  async register(@Body() body: { username: string; email: string; password: string }) {
    const { username, email, password } = body;

    // Log registration for compliance
    this.logger.log(`registration_attempt user=${username} email=${email}`);

    // Simulate registration
    this.logger.log(`registration_success user=${username} role=standard`);
    return { success: true, message: 'User registered' };
  }
}

@Module({
  controllers: [AuthController],
  providers: [AuthService],
})
class AppModule {
  configure(consumer: MiddlewareConsumer) {
    consumer.apply(AuditMiddleware).forRoutes('*');
  }
}

async function bootstrap() {
  const app = await NestFactory.create(AppModule, {
    logger: ['log', 'warn', 'error'],
  });

  // Logs shipped to CloudWatch via fluentd sidecar
  await app.listen(3000);
}

bootstrap();
